(function(root){'use strict';const S=root.Staff||(typeof module==='object'&&module.exports?require('./staff-model.js'):null),C=root.DailyCashCount||(typeof module==='object'&&module.exports?require('./daily-cash-count.js'):null),hash=v=>typeof v==='string'&&/^[0-9a-f]{64}$/.test(v),fail=()=>{throw Error('بەڵگەی داخستنی سندوق پشتڕاست نەکرایەوە.');};
function day(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v)||v<'0001-01-01')fail();const d=new Date(v+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)fail();return v;}
function num(v,signed=false){if(typeof v!=='string'||!(signed?/^(0|-?[1-9][0-9]{0,38})$/:/^(0|[1-9][0-9]{0,38})$/).test(v))fail();return BigInt(v);}
function cash(r,d){if(r?.day!==d||r.currency!=='IQD'||r.timezone!=='Asia/Baghdad')fail();const c=r.cash;if(!c)fail();for(const k of ['count','opening','inflows','outflows','closing'])num(c[k]);if(num(c.closing)!==num(c.opening)+num(c.inflows)-num(c.outflows))fail();return c;}
function payload(p,owner){if(p?.owner!==owner||!S.uuid(owner)||!S.uuid(p.id)||!hash(p.hash)||typeof p.note!=='string'||p.note!==p.note.trim()||p.note.length>500||C.parse(p.actual)!==p.actual)fail();day(p.day);return p;}
function row(r,owner,d,p){if(!S.uuid(r?.id)||r.owner_id!==owner||r.day!==d||!S.date(r.created_at)||!hash(r.source_hash)||typeof r.note!=='string'||r.note!==r.note.trim()||r.note.length>500)fail();const c=cash(r.report_snapshot,d);if(C.parse(r.actual)!==r.actual||num(r.expected)!==num(c.closing)||num(r.difference,true)!==num(r.actual)-num(r.expected)||r.difference!=='0'&&!r.note)fail();if(p&&(r.id!==p.id||r.actual!==p.actual||r.note!==p.note||r.source_hash!==p.hash))fail();return r;}
function preview(v,owner,d){day(d);if(v?.scope!=='daily-close-preview-v1'||v.owner_id!==owner||v.day!==d||v.currency!=='IQD'||v.timezone!=='Asia/Baghdad'||!hash(v.snapshot_hash))fail();cash(v.report,d);if(v.close!==null)row(v.close,owner,d);return v;}
function receipt(v,owner,p){payload(p,owner);if(v?.scope!=='daily-close-receipt-v1'||v.owner_id!==owner)fail();return row(v.close,owner,p.day,p);}
function csv(r,owner){row(r,owner,r.day);const cell=x=>'"'+String(x).replaceAll('"','""')+'"',note=/^[\s\uFEFF]*[=+\-@]/.test(r.note)?"'"+r.note:r.note;return '\ufeff'+[['ناسنامەی داخستن','ڕۆژ','باڵانسی ڕاپۆرت / دینار','ژمێردراو / دینار','جیاوازی / دینار','هۆکار','کاتی تۆمارکردن'],[r.id,r.day,r.expected,r.actual,r.difference,note,r.created_at]].map(a=>a.map(cell).join(',')).join('\r\n');}
function selection(search){const q=new URLSearchParams(search);if(![...q.keys()].length)return null;if([...q.keys()].some(k=>k!=='day')||q.getAll('day').length!==1)fail();return day(q.get('day'));}
root.DailyClose={selection,day,payload,row,preview,receipt,csv};if(typeof module==='object'&&module.exports)module.exports=root.DailyClose;})(globalThis);
